<?php require __DIR__.'/../includes/bootstrap.php';require_role(['admin']);$title='Administration Voyalo';$stats=[];foreach(['users'=>'Voyageurs','hotels'=>'Hébergements','routes'=>'Trajets','packages'=>'Circuits'] as $table=>$label)$stats[$label]=(int)$pdo->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();$revenue=(float)$pdo->query("SELECT COALESCE(SUM(montant),0) FROM payments WHERE statut='reussi' AND created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')")->fetchColumn();$recent=$pdo->query("SELECT 'Hôtel' nature,b.id,u.nom client,b.prix_total montant,b.statut,b.created_at FROM room_bookings b JOIN users u ON u.id=b.user_id UNION ALL SELECT 'Billet',b.id,u.nom,b.prix_total,b.statut,b.created_at FROM ticket_bookings b JOIN users u ON u.id=b.user_id UNION ALL SELECT 'Circuit',b.id,u.nom,b.prix_total,b.statut,b.created_at FROM package_bookings b JOIN users u ON u.id=b.user_id ORDER BY created_at DESC LIMIT 8")->fetchAll();require __DIR__.'/../includes/header.php';?>
<section class="max-w-7xl mx-auto px-4 pb-12"><div class="page-heading flex flex-wrap justify-between items-end gap-4"><div><p class="page-eyebrow">Administration · Voyalo</p><h1 class="page-title">Vue d'ensemble</h1><p class="page-subtitle">Suivez l'activité de votre agence.</p></div><a href="/admin/export.php" class="btn">Exporter les réservations ↓</a></div><div class="grid sm:grid-cols-2 lg:grid-cols-5 gap-4 mt-5"><?php foreach($stats as $k=>$v):?><article class="dashboard-stat"><span><?=e($k)?></span><strong><?=$v?></strong></article><?php endforeach;?><article class="dashboard-stat"><span>Ventes du mois</span><strong class="!text-2xl"><?=money($revenue)?></strong></article></div>
<div class="flex justify-between items-end mt-10"><div><p class="page-eyebrow">Gestion de l'agence</p><h2 class="text-2xl font-black mt-1">Raccourcis</h2></div></div><div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-3 mt-4"><a class="admin-link" href="/admin/catalog.php?kind=hotels">Hébergements <span>→</span></a><a class="admin-link" href="/admin/catalog.php?kind=rooms">Chambres <span>→</span></a><a class="admin-link" href="/admin/catalog.php?kind=routes">Trajets <span>→</span></a><a class="admin-link" href="/admin/catalog.php?kind=schedules">Horaires & places <span>→</span></a><a class="admin-link" href="/admin/catalog.php?kind=packages">Circuits <span>→</span></a><a class="admin-link" href="/admin/catalog.php?kind=departures">Départs circuits <span>→</span></a><a class="admin-link" href="/admin/catalog.php?kind=promotions">Promotions <span>→</span></a><a class="admin-link" href="/admin/catalog.php?kind=users">Utilisateurs & agents <span>→</span></a><a class="admin-link" href="/admin/export.php">Export des ventes <span>↓</span></a><a class="admin-link" href="/agent/index.php">Planning guichet <span>→</span></a></div>
<div class="flex justify-between items-end mt-10"><div><p class="page-eyebrow">Suivi</p><h2 class="text-2xl font-black mt-1">Réservations récentes</h2></div></div><div class="table-wrap mt-4"><table><thead><tr><th>Type</th><th>Client</th><th>Montant</th><th>Statut</th><th>Reçue le</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><span class="pill"><?=e($r['nature'])?></span></td><td><?=e($r['client'])?></td><td><?=money($r['montant'])?></td><td><?=e(str_replace('_',' ',$r['statut']))?></td><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="5">Aucune réservation pour le moment.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
